<?php require __DIR__.'/bootstrap.php';db()->exec("CREATE TABLE IF NOT EXISTS medicos(id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,crm TEXT NOT NULL,especialidade TEXT,email TEXT,senha_hash TEXT NOT NULL,assinatura_path TEXT,logo_path TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS pacientes(id INTEGER PRIMARY KEY AUTOINCREMENT,medico_id INTEGER NOT NULL,nome TEXT NOT NULL,cpf TEXT,nascimento TEXT,sexo TEXT,telefone TEXT,email TEXT,endereco TEXT,observacoes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(medico_id) REFERENCES medicos(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS atendimentos(id INTEGER PRIMARY KEY AUTOINCREMENT,medico_id INTEGER NOT NULL,paciente_id INTEGER NOT NULL,data TEXT NOT NULL,queixa TEXT,historico TEXT,avaliacao TEXT,conduta TEXT,exames TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(medico_id) REFERENCES medicos(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS cid10(id INTEGER PRIMARY KEY AUTOINCREMENT,codigo TEXT UNIQUE NOT NULL,descricao TEXT NOT NULL);CREATE TABLE IF NOT EXISTS documentos(id INTEGER PRIMARY KEY AUTOINCREMENT,medico_id INTEGER NOT NULL,paciente_id INTEGER NOT NULL,tipo TEXT NOT NULL,conteudo TEXT NOT NULL,codigo TEXT UNIQUE NOT NULL,emitido_em TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(medico_id) REFERENCES medicos(id) ON DELETE CASCADE);CREATE TABLE IF NOT EXISTS modelos(id INTEGER PRIMARY KEY AUTOINCREMENT,medico_id INTEGER NOT NULL,tipo TEXT NOT NULL,nome TEXT NOT NULL,conteudo TEXT NOT NULL,ativo INTEGER DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(medico_id) REFERENCES medicos(id) ON DELETE CASCADE);");echo 'Banco inicializado.';